227	<body>
228	  <main>
229	    <h1 class="visually-hidden">Animated Circle</h1>
230	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
231	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
232	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
233	      </svg>
234	    </button>
235	    <p class="status" id="status" role="status">Blue</p>
236	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
237	  </main>
238	  <script>
239	    const config = {
240	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
241	      storageKey: 'circle-color',
242	      hapticDuration: 50,
243	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
244	    };
245	
246	    const DOM = {
247	      button: document.querySelector('.circle'),
248	      status: document.querySelector('.status'),
249	      helpButton: document.querySelector('.help-button'),
250	      keyHint: document.querySelector('.keys'),
251	      verbSpan: document.querySelector('.hint .verb'),
252	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
253	    };
254	
255	    const state = {
256	      index: 0,
257	      shiftHeld: false,
258	      hoverCapable: !matchMedia('(hover: none)').matches,
259	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
260	      hoverQuery: matchMedia('(hover: none)'),
261	    };
262	
263	    function loadColor() {
264	      try {
265	        return localStorage.getItem(config.storageKey);
266	      } catch {
267	        return null;
268	      }
269	    }
270	
271	    function saveColor(color) {
272	      try {
273	        localStorage.setItem(config.storageKey, color);
274	      } catch {}
275	    }
276	
277	    function applyColor() {
278	      const color = config.colors[state.index];
279	      DOM.button.dataset.color = color === 'blue' ? '' : color;
280	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
281	    }
282	
283	    function setIndex(next, { haptic = false } = {}) {
284	      if (next === state.index) return;
285	      state.index = next;
286	      applyColor();
287	      saveColor(config.colors[state.index]);
288	
289	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
290	
291	      if (state.reducedMotion.matches) return;
292	      DOM.button.classList.remove('color-changed');
293	      void DOM.button.offsetWidth;
294	      DOM.button.classList.add('color-changed');
295	    }
296	
297	    function changeColor(step) {
298	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
299	    }
300	
301	    function updateDeviceVerbs() {
302	      state.hoverCapable = !state.hoverQuery.matches;
303	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
304	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
305	    }
306	
307	    function toggleKeyHintVisibility() {
308	      const expanded = DOM.keyHint.classList.toggle('visible');
309	      DOM.helpButton.setAttribute('aria-expanded', expanded);
310	    }
311	
312	    function handleKeyDown(event) {
313	      if (event.key === 'Enter' || event.key === ' ') {
314	        if (!event.repeat) state.shiftHeld = event.shiftKey;
315	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
316	        return;
317	      }
318	
319	      if (event.altKey || event.ctrlKey || event.metaKey) return;
320	
321	      if (event.key in config.keySteps) {
322	        event.preventDefault();
323	        changeColor(config.keySteps[event.key]);
324	      } else if (event.key === 'Home') {
325	        event.preventDefault();
326	        setIndex(0, { haptic: true });
327	      } else if (event.key === 'End') {
328	        event.preventDefault();
329	        setIndex(config.colors.length - 1, { haptic: true });
330	      }
331	    }
332	
333	    // Initialize
334	    const savedColor = loadColor();
335	    state.index = config.colors.includes(savedColor) ? config.colors.indexOf(savedColor) : 0;
336	    applyColor();
337	
338	    requestAnimationFrame(() => requestAnimationFrame(() => {
339	      DOM.button.classList.remove('no-transition');
340	    }));
341	
342	    updateDeviceVerbs();
343	    state.hoverQuery.addEventListener('change', updateDeviceVerbs);
344	
345	    if (state.hoverCapable) {
346	      DOM.keyHint.classList.add('visible');
347	      DOM.helpButton.setAttribute('aria-expanded', 'true');
348	    }
349	
350	    // Event listeners
351	    DOM.button.addEventListener('keydown', handleKeyDown);
352	    DOM.button.addEventListener('keyup', (event) => {
353	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
354	    });
355	    DOM.button.addEventListener('blur', () => {
356	      state.shiftHeld = false;
357	    });
358	    DOM.button.addEventListener('click', (event) => {
359	      if (event.detail > 1) return;
360	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
361	      state.shiftHeld = false;
362	    });
363	    DOM.button.addEventListener('dblclick', (event) => {
364	      event.preventDefault();
365	      setIndex(0);
366	    });
367	    DOM.button.addEventListener('animationend', () => {
368	      DOM.button.classList.remove('color-changed');
369	    });
370	
371	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
372	
373	    addEventListener('storage', (event) => {
374	      if (event.key !== config.storageKey && event.key !== null) return;
375	      const newIndex = config.colors.indexOf(event.newValue);
376	      state.index = newIndex === -1 ? 0 : newIndex;
377	      applyColor();
378	    });
379	  </script>
380	</body>
381	</html>
