def lin(c):
    c/=255
    return c/12.92 if c<=0.03928 else ((c+0.055)/1.055)**2.4
def L(rgb): return 0.2126*lin(rgb[0])+0.7152*lin(rgb[1])+0.0722*lin(rgb[2])
def hexrgb(h): h=h.lstrip('#'); h=''.join(c*2 for c in h) if len(h)==3 else h; return [int(h[i:i+2],16) for i in (0,2,4)]
def cr(a,b):
    la,lb=L(a),L(b); 
    if la<lb: la,lb=lb,la
    return (la+0.05)/(lb+0.05)
def blend(fg,bg,a): return [a*f+(1-a)*b for f,b in zip(fg,bg)]
for name,bg,cols in [('light','#fff',dict(blue='#2563eb',red='#dc2626',green='#16a34a',amber='#d97706',violet='#7c3aed',cyan='#0891b2',green700='#15803d',amber700='#b45309',cyan700='#0e7490')),
                     ('dark','#111',dict(blue='#93c5fd',red='#fca5a5',green='#86efac',amber='#fcd34d',violet='#c4b5fd',cyan='#67e8f9'))]:
    print(name)
    for k,v in cols.items():
        print(f"  {k:9} full={cr(hexrgb(v),hexrgb(bg)):.2f}  @0.85={cr(blend(hexrgb(v),hexrgb(bg),.85),hexrgb(bg)):.2f}")
EOF
